 wc_reduce_stock_levels($order->get_id());test_case('Native order stock reduction',wc_get_product($p->get_id())->get_stock_quantity()===3);wc_increase_stock_levels($order->get_id());test_case('Cancellation stock restoration',wc_get_product($p->get_id())->get_stock_quantity()===5);
