 $variation=new WC_Product_Variation();$variation->set_parent_id($variable->get_id());$variation->set_attributes([sanitize_title('رنگ')=>'طلایی']);$variation->set_regular_price('230000');$variation->set_manage_stock(true);$variation->set_stock_quantity(2);$variation->save();$created[]=$variation->get_id();WC_Product_Variable::sync($variable->get_id());
